async function searchUser(baseUrl: string, token: string, name: string): Promise<UserInfo | null> {
  // Query on last name only (before the first comma) so a 'Last, First' input
  // still returns candidates; top:50 widens the pool for the strict re-filter below.
  const searchTerm = name.split(',')[0].trim();
  const result = await apiRequest(baseUrl, token, 'POST', '/api/v1/entrausers/search', {
    term: searchTerm,
    top: 50,
  });
  // Normalize the payload shape: bare array, or a .value/.users wrapper.
  const users = Array.isArray(result) ? result : (result.value || result.users || []);

  // PASS 1 — exact display-name equality, so the right account beats a near-namesake.
  for (const u of users) {
    const displayName = u.displayName || u.userName || u.name || '';   // field varies by directory
    if (displayName === name) {
      return { userId: u.id || u.userId || '', userName: displayName, userEmail: u.mail || u.userEmail || u.email || '' };
    }
  }
  // PASS 2 — only if no exact hit: case-insensitive contains, as a fallback.
  for (const u of users) {
    const displayName = u.displayName || u.userName || u.name || '';
    if (displayName.toLowerCase().includes(name.toLowerCase())) {
      return { userId: u.id || u.userId || '', userName: displayName, userEmail: u.mail || u.userEmail || u.email || '' };
    }
  }
  return null;   // no match -> null, so the caller drops the recipient instead of guessing
}

function apiRequest(baseUrl: string, token: string, method: string, apiPath: string, body?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const u = new URL(baseUrl + apiPath);
    const data = body ? JSON.stringify(body) : '';
    const req = https.request({
      hostname: u.hostname,
      path: u.pathname,
      method,
      headers: {
        'Authorization': `Bearer ${token}`,   // bearer token on every call
        'Content-Type': 'application/json',
        // byteLength (not string .length) so multibyte prompt text sends a correct header
        'Content-Length': Buffer.byteLength(data),
      },
    }, res => {
      let d = '';
      res.on('data', (c) => d += c);        // raw HTTP arrives in chunks — accumulate
      res.on('end', () => {                 // ...then process the whole body
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          // Tolerate a non-JSON 2xx body: resolve the raw string instead of throwing.
          try { resolve(JSON.parse(d)); } catch { resolve(d); }
        } else {
          // Non-2xx rejects with status + a 200-char slice — enough to diagnose, not a full error page.
          reject(new Error(`API ${res.statusCode}: ${d.slice(0, 200)}`));
        }
      });
    });
    if (data) req.write(data);   // only write a body when there is one
    req.end();
  });
}

// Create conversation — Date.now() in the name keeps each run's conversations
// uniquely identifiable (intentionally non-idempotent, good for regression sweeps).
const conv = await apiRequest(baseUrl, token, 'POST', '/api/v1/conversations', { name: `Share-${Date.now()}` });
const conversationId = conv.id;   // downstream URLs depend on this — enforces create-before-share ordering

// Send the prompt into that conversation and wait for the assistant's answer.
const msg = await apiRequest(baseUrl, token, 'POST', `/api/v1/conversations/${conversationId}`, {
  question: prompt,
  limit: 5,
  service: args.model,
});
const answer = msg.answer || '';
const wordCount = (answer.match(/\S+/g) || []).length;   // || [] -> empty answer counts as 0, never throws

// Share with EVERY already-resolved recipient — name->account happened earlier,
// so this only transmits verified accounts, each at the same run-level role.
const sharePayload = {
  users: resolvedUsers.map(u => ({ userId: u.userId, userName: u.userName, userEmail: u.userEmail, role: args.role })),
};
await apiRequest(baseUrl, token, 'POST', `/api/v1/conversations/${conversationId}/shares`, sharePayload);

const outDir = path.resolve(__dirname, '..', 'outputs', 'reports', 'conversation-shares');
fs.mkdirSync(outDir, { recursive: true });   // build the whole report tree idempotently
// Strip ':' and '.' (illegal/awkward in filenames) and keep second precision;
// tagging with env means parallel runs never clobber each other's report.
const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const outPath = path.join(outDir, `ConvShare_${args.env}_${ts}.json`);
fs.writeFileSync(outPath, JSON.stringify({
  env: args.env,
  model: args.model,
  role: args.role === 0 ? 'read-only' : 'edit',   // decode numeric role back to human-readable
  timestamp: new Date().toISOString(),
  results,   // raw per-conversation record: ids, answers, share success flags
}, null, 2));
